const PERFIL = "Murillo, brasileiro, profissional de dados em um grande banco, migrando de carreira para engenharia de dados e mirando arquitetura de dados com serviços da AWS. Mantém um laboratório pessoal de IA local (Ollama, LiteLLM, n8n, MCP). Não lê inglês: tudo precisa vir em português do Brasil. Interesses: inteligência artificial, tecnologia, dados e nuvem, ciência, astronomia, curiosidades e notícias locais (São Paulo), do Brasil e do mundo.";

const FONTES = $('Fontes').all();
const resp = $input.all();
const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos || {};
const agora = Date.now();
Object.keys(sd.vistos).forEach(k => { if (agora - sd.vistos[k] > 4 * 86400000) delete sd.vistos[k]; });
const limite = agora - 30 * 3600 * 1000;
function ent(s) {
  return String(s || '').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n))).replace(/&#x([0-9a-f]+);/gi, (m, n) => String.fromCharCode(parseInt(n, 16)))
    .replace(/&apos;|&#039;/g, "'").replace(/&amp;/g, '&');
}
function limpar(s) {
  let t = String(s || '').replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, '$1');
  t = ent(t).replace(/<[^>]+>/g, ' ');
  t = ent(t).replace(/<[^>]+>/g, ' ');
  return t.replace(/\s+/g, ' ').trim();
}
function tag(b, nome) {
  const m = new RegExp('<' + nome + '(?:\\s[^>]*)?>([\\s\\S]*?)</' + nome + '>', 'i').exec(b);
  return m ? m[1] : '';
}
function link(b) {
  const re = /<link\b([^>]*?)(?:\/>|>([\s\S]*?)<\/link>)/gi;
  let m;
  let achado = '';
  while ((m = re.exec(b))) {
    const attrs = m[1] || '';
    const href = /href="([^"]+)"/i.exec(attrs);
    if (href) {
      const rel = /rel="([^"]+)"/i.exec(attrs);
      if (!rel || rel[1] === 'alternate') return ent(href[1]);
    } else if (m[2]) {
      const u = limpar(m[2]);
      if (/^https?:/i.test(u)) achado = achado || u;
    }
  }
  if (achado) return achado;
  const g = /<guid[^>]*>\s*(https?:[^<\s]+)/i.exec(b);
  return g ? g[1] : '';
}
const porFonte = [];
const falhas = [];
resp.forEach((r, i) => {
  const f = (FONTES[i] || { json: { cat: '?', nome: '?' } }).json;
  const xml = String((r.json || {}).data || '');
  if (!xml || !/<(item|entry)[\s>]/i.test(xml)) { falhas.push(f.nome); return; }
  const itens = [];
  const re = /<(item|entry)[\s>][\s\S]*?<\/\1>/gi;
  let m;
  while ((m = re.exec(xml)) && itens.length < 15) {
    const b = m[0];
    const titulo = limpar(tag(b, 'title'));
    const url = link(b);
    if (!titulo || !url || sd.vistos[url]) continue;
    const data = Date.parse(limpar(tag(b, 'pubDate') || tag(b, 'published') || tag(b, 'updated') || tag(b, 'dc:date')));
    if (!isNaN(data) && data < limite) continue;
    const trecho = limpar(tag(b, 'description') || tag(b, 'summary') || tag(b, 'content:encoded') || tag(b, 'content')).slice(0, 400);
    itens.push({ cat: f.cat, fonte: f.nome, titulo: titulo.slice(0, 200), link: url, trecho });
  }
  porFonte.push({ nome: f.nome, itens });
});
const cand = [];
for (let rodada = 0; cand.length < 50; rodada++) {
  let algum = false;
  for (const pf of porFonte) {
    const it = pf.itens[rodada];
    if (it) { algum = true; if (cand.length < 50) cand.push(it); }
  }
  if (!algum) break;
}
cand.forEach((c, n) => { c.id = n + 1; });
if (cand.length === 0) return [];
const lista = cand.map(c => c.id + ' | ' + c.cat + ' | ' + c.fonte + ' | ' + c.titulo + ' | ' + c.trecho.slice(0, 140)).join('\n');
const SYS = 'Você é um curador editorial pessoal e criterioso. Perfil do leitor: ' + PERFIL;
const USER = 'Abaixo há uma lista numerada de notícias e artigos recentes (id | categoria | fonte | título | trecho). Escolha no máximo 7 itens realmente relevantes para este leitor. Descarte repetições, sensacionalismo, previsões vagas e assuntos sem utilidade. Mantenha variedade de categorias, no máximo 2 por categoria, e não escolha duas matérias sobre o mesmo fato. Dê a cada escolhido uma nota de 1 a 10 de relevância para o perfil. Responda somente com JSON: um objeto com a chave escolhidos, cuja lista contém objetos com as chaves id, nota e motivo (uma frase).\n\n' + lista;
return [{ json: { candidatos: cand, falhas, fontesLidas: porFonte.length, fontesTotal: resp.length,
  req: { model: '__MODELO__', temperature: 0.2, max_tokens: 700, stream: false, response_format: { type: 'json_object' },
    messages: [ { role: 'system', content: SYS }, { role: 'user', content: USER } ] } } }];

const cands = $('Analisar feeds').first().json.candidatos;
const txt = String(((((($input.first().json || {}).choices || [])[0]) || {}).message || {}).content || '');
let j = {};
try { j = JSON.parse(txt); } catch (e) {
  const m = /\{[\s\S]*\}/.exec(txt);
  try { j = m ? JSON.parse(m[0]) : {}; } catch (e2) { j = {}; }
}
const esc = Array.isArray(j.escolhidos) ? j.escolhidos : [];
const usados = new Set();
const porCat = {};
const out = [];
esc.map(e => ({ id: Number(e.id), nota: Number(e.nota) || 0, motivo: String(e.motivo || '') }))
  .sort((a, b) => b.nota - a.nota)
  .forEach(e => {
    const c = cands.find(x => x.id === e.id);
    if (c && !usados.has(c.id) && e.nota >= 6 && out.length < 7 && (porCat[c.cat] || 0) < 2) {
      usados.add(c.id);
      porCat[c.cat] = (porCat[c.cat] || 0) + 1;
      out.push({ json: Object.assign({}, c, { nota: e.nota, motivo: e.motivo }) });
    }
  });
return out;

const sel = $('Selecionar').all();
function ent(s) {
  return String(s || '').replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"')
    .replace(/&#(\d+);/g, (m, n) => String.fromCharCode(Number(n))).replace(/&amp;/g, '&');
}
function limpar(s) { return ent(String(s || '').replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim(); }
function texto(html) {
  let h = String(html || '').replace(/<(script|style|noscript|nav|header|footer|aside|form|svg)[\s\S]*?<\/\1>/gi, ' ');
  const art = /<article[\s\S]*?<\/article>/i.exec(h);
  if (art) h = art[0];
  const ps = [];
  const re = /<p[\s>][\s\S]*?<\/p>/gi;
  let m;
  while ((m = re.exec(h))) { const t = limpar(m[0]); if (t.length > 60) ps.push(t); }
  return ps.join(' ');
}
return $input.all().map((r, i) => {
  const c = sel[i].json;
  let t = texto((r.json || {}).data).slice(0, 1800);
  let origem = 'texto da matéria';
  if (t.length < 250) { t = c.trecho; origem = 'apenas o trecho do feed'; }
  return { json: Object.assign({}, c, { texto: t, origem, embedInput: c.titulo + '\n' + t.slice(0, 600) }) };
});

const emb = $('Embedding').all();
const base = $('Preparar contexto').all();
const ruim = t => /^(C[ée]rebro: |Digest \d{4}-)/.test(String(t || ''));
return $input.all().map((r, i) => {
  const v = ((((emb[i] || { json: {} }).json || {}).embeddings) || [])[0];
  const pts = ((((r.json || {}).result) || {}).points || [])
    .filter(p => p.payload && (p.score || 0) >= 0.55 && !ruim(p.payload.titulo))
    .slice(0, 2)
    .map(p => ({ titulo: String(p.payload.titulo || ''), trecho: String(p.payload.trecho || '').slice(0, 300) }));
  return { json: Object.assign({}, base[i].json, { vetor: Array.isArray(v) ? v : null, notas: pts }) };
});

const base = $('Guardar notas').all();
const SYS = 'Você é um assistente de leitura. Escreva em português do Brasil, de forma objetiva e factual. Não inspire, não motive e não sugira o que o leitor poderia fazer. Use apenas fatos presentes no TEXTO e nas FONTES DO LEITOR. Não invente nada.';
return $input.all().map((r, i) => {
  const c = base[i].json;
  const livros = ((((r.json || {}).result) || {}).points || [])
    .filter(p => p.payload && (p.score || 0) >= 0.58)
    .slice(0, 2)
    .map(p => ({ titulo: String(p.payload.source || 'livro').split('/').pop().replace(/\.[A-Za-z0-9]+$/, ''), trecho: String(p.payload.text || '').slice(0, 300) }));
  const refs = {};
  const linhas = [];
  (c.notas || []).forEach((n, k) => { refs['N' + (k + 1)] = 'Nota: ' + n.titulo; linhas.push('[N' + (k + 1) + '] Nota "' + n.titulo + '": ' + n.trecho); });
  livros.forEach((l, k) => { refs['L' + (k + 1)] = 'Livro: ' + l.titulo; linhas.push('[L' + (k + 1) + '] Livro "' + l.titulo + '": ' + l.trecho); });
  const user = 'MATÉRIA\nFonte: ' + c.fonte + ' (' + c.cat + ')\nTítulo original: ' + c.titulo + '\nConteúdo (' + c.origem + '): ' + c.texto
    + '\n\nFONTES DO LEITOR (notas e livros que ele já tem; pode estar vazio)\n' + (linhas.length ? linhas.join('\n') : '(nenhuma fonte relacionada encontrada)')
    + '\n\nResponda somente com JSON com as chaves: titulo_pt (o título traduzido para o português); resumo (3 a 4 frases com o que a matéria informa: fatos, números, quem, quando, sem opinião); conexao (lista de objetos com ref e explicacao; inclua somente se uma fonte do leitor tratar do MESMO assunto ou de um ponto técnico diretamente ligado ao fato, e explique em uma ou duas frases qual é a ligação concreta; não force ligações por associação vaga, como "ambos envolvem dados"; se nenhuma fonte servir, use lista vazia); relevancia (1 a 2 frases objetivas sobre por que a informação é relevante em si: quem afeta, magnitude, o que muda); pontos (lista de 2 a 3 frases curtas com fatos ou implicações da matéria que merecem atenção).';
  return { json: { id: c.id, cat: c.cat, fonte: c.fonte, titulo: c.titulo, link: c.link, trecho: c.trecho, motivo: c.motivo, refs,
    req: { model: '__MODELO__', temperature: 0.2, max_tokens: 900, stream: false, response_format: { type: 'json_object' },
      messages: [ { role: 'system', content: SYS }, { role: 'user', content: user } ] } } };
});

const base = $('Montar pedidos').all().map(i => i.json);
const an = $('Analisar feeds').first().json;
let d = null;
try { if (typeof $now !== 'undefined') d = $now; } catch (e) { d = null; }
const hh = d ? d.toFormat('HH') : String(new Date().getHours()).padStart(2, '0');
const dataIso = d ? d.toFormat('yyyy-LL-dd') : new Date().toISOString().slice(0, 10);
let extenso = dataIso;
try { extenso = d.setLocale('pt-BR').toFormat("cccc, d 'de' LLLL 'de' yyyy"); } catch (e) { extenso = dataIso; }
const porCat = {};
let ligados = 0;
const blocos = [];
const titulosBark = [];
$input.all().forEach((r, i) => {
  const c = base[i];
  const txt = String(((((r.json || {}).choices || [])[0]) || {}).message && r.json.choices[0].message.content || '');
  let j = {};
  try { j = JSON.parse(txt); } catch (e) {
    const m = /\{[\s\S]*\}/.exec(txt);
    try { j = m ? JSON.parse(m[0]) : {}; } catch (e2) { j = {}; }
  }
  porCat[c.cat] = (porCat[c.cat] || 0) + 1;
  const tituloPt = String(j.titulo_pt || '').trim() || c.titulo;
  const resumo = String(j.resumo || '').trim() || (c.trecho ? c.trecho.slice(0, 300) : 'Resumo indisponível.');
  const conex = (Array.isArray(j.conexao) ? j.conexao : [])
    .map(x => ({ rotulo: c.refs[String((x || {}).ref)], expl: String((x || {}).explicacao || '').trim() }))
    .filter(x => x.rotulo && x.expl);
  const relev = String(j.relevancia || '').trim() || c.motivo || 'Selecionada na triagem.';
  const pontos = (Array.isArray(j.pontos) ? j.pontos : (j.pontos ? [j.pontos] : [])).map(s => String(s).trim()).filter(Boolean);
  const b = ['## ' + (i + 1) + '. ' + tituloPt, c.cat + ' · ' + c.fonte];
  if (tituloPt !== c.titulo) b.push('Título original: ' + c.titulo);
  b.push('', '**Resumo:** ' + resumo, '');
  if (conex.length) {
    ligados++;
    b.push('**Por que importa para você (ligado ao que você tem):**');
    conex.forEach(x => b.push('- [' + x.rotulo + '] ' + x.expl));
    b.push('');
  } else {
    b.push('**Por que importa:** Sem ligação com as suas notas ou estudos. ' + relev, '');
  }
  if (pontos.length) { b.push('**Pontos de atenção:**'); pontos.forEach(s => b.push('- ' + s)); b.push(''); }
  b.push('[Ler a matéria completa](' + c.link + ')', '');
  blocos.push(b.join('\n'));
  if (titulosBark.length < 4) titulosBark.push((i + 1) + '. ' + tituloPt);
});
const intro = base.length + ' matérias: ' + Object.keys(porCat).map(k => porCat[k] + ' em ' + k).join(', ') + '. '
  + ligados + ' ligada(s) às suas notas ou estudos.';
const rodape = 'Fontes lidas: ' + an.fontesLidas + ' de ' + an.fontesTotal
  + (an.falhas.length ? '. Sem itens novos ou sem resposta: ' + an.falhas.join(', ') : '') + '.';
const markdown = ['# Digest das ' + hh + 'h', extenso, '', intro, ''].concat(blocos).concat(['---', rodape]).join('\n');
const sd = $getWorkflowStaticData('global');
sd.vistos = sd.vistos || {};
an.candidatos.forEach(c => { sd.vistos[c.link] = Date.now(); });
const bark = intro + '\n' + titulosBark.join('\n') + '\nO digest completo está no app Notas, pasta Digest.';
return [{ json: { titulo: 'Digest ' + dataIso + ' ' + hh + 'h', markdown, bark, hh, total: base.length } }];
